package com.mailservice.api;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.logging.Logger;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/mail/*")
public class EmailServiceServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(EmailServiceServlet.class.getName());
    private final ExecutorService emailExecutor = Executors.newFixedThreadPool(4);
    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private final ConcurrentHashMap<String, EmailTask> pendingTasks = new ConcurrentHashMap<>();
    private final EmailTemplateEngine templateEngine = new EmailTemplateEngine();

    @Override
    public void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        if (shuttingDown.get()) {
            resp.setStatus(503);
            resp.setContentType("text/html; charset=UTF-8");
            PrintWriter out = resp.getWriter();
            out.println("<html><body><h1>Service Unavailable</h1></body></html>");
            return;
        }

        String recipient = req.getParameter("to");
        String subject = req.getParameter("subject");
        String body = req.getParameter("body");
        String callbackUrl = req.getParameter("callback");

        if (recipient == null || subject == null || body == null) {
            resp.setStatus(400);
            return;
        }

        String taskId = java.util.UUID.randomUUID().toString();
        EmailTask task = new EmailTask(taskId, recipient, subject, body, callbackUrl);
        pendingTasks.put(taskId, task);

        emailExecutor.submit(() -> processEmail(task));

        resp.setStatus(202);
        resp.setContentType("application/json");
        resp.getWriter().write("{\"taskId\":\"" + taskId + "\"}");
    }

    @Override
    public void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String pathInfo = req.getPathInfo();
        resp.setContentType("text/html; charset=UTF-8");
        PrintWriter out = resp.getWriter();

        if (pathInfo != null && pathInfo.startsWith("/status/")) {
            String taskId = pathInfo.substring("/status/".length());
            EmailTask task = pendingTasks.get(taskId);

            if (task == null) {
                resp.setStatus(404);
                out.println("<html><body><p>Task not found</p></body></html>");
                return;
            }

            String statusPage = buildStatusPage(task);
            out.println(statusPage);
        } else if (pathInfo != null && pathInfo.equals("/health")) {
            out.println("<html><body><p>OK</p></body></html>");
        } else {
            resp.setStatus(404);
        }
    }

    private String buildStatusPage(EmailTask task) {
        StringBuilder sb = new StringBuilder();
        sb.append("<html><head><title>Email Status</title></head><body>");
        sb.append("<h1>Email Delivery Status</h1>");
        sb.append("<div class='status-card'>");
        sb.append("<p>Task ID: ").append(StringEscapeUtils.escapeHtml4(task.getTaskId())).append("</p>");
        sb.append("<p>Recipient: ").append(StringEscapeUtils.escapeHtml4(task.getRecipient())).append("</p>");
        sb.append("<p>Subject: ").append(StringEscapeUtils.escapeHtml4(task.getSubject())).append("</p>");
        sb.append("<p>Status: ").append(StringEscapeUtils.escapeHtml4(task.getStatus())).append("</p>");

        if (task.getCallbackUrl() != null) {
            sb.append(buildCallbackSection(task));
        }

        sb.append("</div></body></html>");
        return sb.toString();
    }

    private String buildCallbackSection(EmailTask task) {
        StringBuilder sb = new StringBuilder();
        String sanitizedCallback = sanitizeUrl(task.getCallbackUrl());
        sb.append("<div class='callback-info'>");
        sb.append("<p>Callback configured</p>");
        sb.append("<script>");
        sb.append("document.addEventListener('DOMContentLoaded', function() {");
        sb.append("  var statusEl = document.getElementById('live-status');");
        sb.append("  var callbackEndpoint = '").append(sanitizedCallback).append("';");
        sb.append("  if (statusEl) { statusEl.dataset.callback = callbackEndpoint; }");
        sb.append("});");
        sb.append("</script>");
        sb.append("<span id='live-status' data-taskid='").append(StringEscapeUtils.escapeHtml4(task.getTaskId())).append("'></span>");
        sb.append("</div>");
        return sb.toString();
    }

    private String sanitizeUrl(String url) {
        if (url == null) return "";
        // Remove obvious script injection attempts
        String cleaned = url.replaceAll("[<>\"]", "");
        // Validate URL scheme
        if (cleaned.startsWith("http://") || cleaned.startsWith("https://")) {
            return cleaned;
        }
        // Allow protocol-relative URLs for flexibility
        if (cleaned.startsWith("//")) {
            return cleaned;
        }
        return "";
    }

    private void processEmail(EmailTask task) {
        try {
            task.setStatus("PROCESSING");
            Thread.sleep(100); // Simulate SMTP connection
            // Actual email sending logic would go here
            task.setStatus("DELIVERED");
            logger.info("Email delivered: " + task.getTaskId());
        } catch (InterruptedException e) {
            task.setStatus("FAILED");
            Thread.currentThread().interrupt();
        }
    }

    @Override
    public void destroy() {
        shuttingDown.set(true);
        emailExecutor.shutdown();
        try {
            if (!emailExecutor.awaitTermination(30, TimeUnit.SECONDS)) {
                emailExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            emailExecutor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    static class EmailTask {
        private final String taskId;
        private final String recipient;
        private final String subject;
        private final String body;
        private final String callbackUrl;
        private volatile String status = "QUEUED";

        EmailTask(String taskId, String recipient, String subject, String body, String callbackUrl) {
            this.taskId = taskId;
            this.recipient = recipient;
            this.subject = subject;
            this.body = body;
            this.callbackUrl = callbackUrl;
        }

        public String getTaskId() { return taskId; }
        public String getRecipient() { return recipient; }
        public String getSubject() { return subject; }
        public String getBody() { return body; }
        public String getCallbackUrl() { return callbackUrl; }
        public String getStatus() { return status; }
        public void setStatus(String status) { this.status = status; }
    }

    static class EmailTemplateEngine {
        public String render(String template, java.util.Map<String, String> vars) {
            String result = template;
            for (java.util.Map.Entry<String, String> entry : vars.entrySet()) {
                result = result.replace("{{" + entry.getKey() + "}}", StringEscapeUtils.escapeHtml4(entry.getValue()));
            }
            return result;
        }
    }
}
